import { index, pgTable, text, timestamp, uuid } from 'drizzle-orm/pg-core';
import { invitation } from './auth.js';

// Auth-adjacent tables owned by the app (not generated by the Better Auth CLI). No RLS: they are
// reached by the unprivileged role through the blanket grants from ensureAppRole.

/**
 * One row per password sign-in attempt, keyed by lower-cased email (existing or not) and client IP.
 * Rows are written before the password is checked and removed again on success, so what remains
 * are failures (or attempts in flight).
 */
export const signInFailure = pgTable(
  'sign_in_failure',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    email: text('email').notNull(),
    ip: text('ip').notNull().default(''),
    attemptedAt: timestamp('attempted_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index('sign_in_failure_email_attempted_at_idx').on(t.email, t.attemptedAt),
    index('sign_in_failure_email_ip_attempted_at_idx').on(t.email, t.ip, t.attemptedAt),
    index('sign_in_failure_attempted_at_idx').on(t.attemptedAt),
  ],
);

/**
 * Registration secret for an invitation: only the sha256 hash is stored; the raw token is shown
 * once to the inviter. Knowing an invitation id alone must never allow registration.
 */
export const invitationToken = pgTable('invitation_token', {
  invitationId: text('invitation_id')
    .primaryKey()
    .references(() => invitation.id, { onDelete: 'cascade' }),
  tokenHash: text('token_hash').notNull(),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  usedAt: timestamp('used_at', { withTimezone: true }),
});
